pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        address currentOwnerBefore;
        try c.owner() returns (address __r) { currentOwnerBefore = __r; } catch { return; }
        bool revertFlag;
        try c.setOwner(newOwner) returns (bool success) {
            revertFlag = !success;
        } catch {
            revertFlag = true;
        }
        address currentOwnerAfter;
        try c.owner() returns (address __r) { currentOwnerAfter = __r; } catch { return; }
        assertTrue(!revertFlag ? currentOwnerAfter == newOwner : currentOwnerAfter == currentOwnerBefore);
    }

